const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const edges = [];
for (let i = 0; i < m; i++) edges.push([tok[4 + 3 * i], tok[2 + 3 * i], tok[3 + 3 * i]]);
edges.sort((x, y) => x[0] - y[0]);
const parent = Array.from({ length: n + 1 }, (_, i) => i);
const find = (x) => {
  let root = x;
  while (parent[root] !== root) root = parent[root];
  while (parent[x] !== root) { const nx = parent[x]; parent[x] = root; x = nx; }
  return root;
};
let total = 0, used = 0;
for (const [w, a, b] of edges) {
  const ra = find(a), rb = find(b);
  if (ra !== rb) { parent[ra] = rb; total += w; used++; }
}
console.log(used === n - 1 ? total : "IMPOSSIBLE");

