import java.util.*;

public class Main {
    static int[] parent;

    static int find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != root) {
            int nx = parent[x];
            parent[x] = root;
            x = nx;
        }
        return root;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        long[][] edges = new long[m][3];
        for (int i = 0; i < m; i++) {
            edges[i][1] = sc.nextLong();
            edges[i][2] = sc.nextLong();
            edges[i][0] = sc.nextLong();
        }
        Arrays.sort(edges, (x, y) -> Long.compare(x[0], y[0]));
        parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = i;
        long total = 0;
        int used = 0;
        for (long[] e : edges) {
            int ra = find((int) e[1]), rb = find((int) e[2]);
            if (ra != rb) {
                parent[ra] = rb;
                total += e[0];
                used++;
            }
        }
        System.out.println(used == n - 1 ? String.valueOf(total) : "IMPOSSIBLE");
    }
}

