#include <bits/stdc++.h>
using namespace std;
vector<int> parent_;
int findRoot(int x) {
    int root = x;
    while (parent_[root] != root) root = parent_[root];
    while (parent_[x] != root) {
        int nx = parent_[x];
        parent_[x] = root;
        x = nx;
    }
    return root;
}
int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    vector<array<long long, 3>> edges(m);
    for (int i = 0; i < m; i++) {
        long long a, b, w;
        scanf("%lld %lld %lld", &a, &b, &w);
        edges[i] = {w, a, b};
    }
    sort(edges.begin(), edges.end());
    parent_.resize(n + 1);
    for (int i = 0; i <= n; i++) parent_[i] = i;
    long long total = 0;
    int used = 0;
    for (auto& e : edges) {
        int ra = findRoot((int)e[1]), rb = findRoot((int)e[2]);
        if (ra != rb) {
            parent_[ra] = rb;
            total += e[0];
            used++;
        }
    }
    if (used == n - 1) printf("%lld\n", total);
    else puts("IMPOSSIBLE");
    return 0;
}
